services/auth/src/main/java/boxoffice/auth/TokenService.java<pre><code>package boxoffice.auth;

import com.nimbusds.jose.JOSEException;
import com.nimbusds.jose.JOSEObjectType;
import com.nimbusds.jose.JWSAlgorithm;
import com.nimbusds.jose.JWSHeader;
import com.nimbusds.jose.crypto.RSASSASigner;
import com.nimbusds.jose.jwk.JWKSet;
import com.nimbusds.jose.jwk.KeyUse;
import com.nimbusds.jose.jwk.RSAKey;
import com.nimbusds.jose.jwk.gen.RSAKeyGenerator;
import com.nimbusds.jwt.JWTClaimsSet;
import com.nimbusds.jwt.SignedJWT;
import java.time.Duration;
import java.time.Instant;
import java.util.Date;
import java.util.Map;
import java.util.UUID;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * Signs JWTs with a private RSA key (RS256) and publishes the public key as a JWKS.
 * Only auth holds the private key; anyone can verify a token with the public one.
 */
@Component
public class TokenService {

    private final RSAKey key;
    private final String issuer;
    private final String audience;
    private final Duration ttl;

    public TokenService(@Value("${jwt.issuer}") String issuer,
                        @Value("${jwt.audience}") String audience,
                        @Value("${jwt.ttl}") Duration ttl) throws JOSEException {
        // a new key pair at every start: fine for a lab, see the warning in the text
        this.key = new RSAKeyGenerator(2048)
                .keyID(UUID.randomUUID().toString())
                .keyUse(KeyUse.SIGNATURE)
                .algorithm(JWSAlgorithm.RS256)
                .generate();
        this.issuer = issuer;
        this.audience = audience;
        this.ttl = ttl;
    }

    public TokenOut issue(User user) {
        var now = Instant.now();
        var claims = new JWTClaimsSet.Builder()
                .issuer(issuer)
                .audience(audience)
                .subject(user.getId().toString())
                .claim("email", user.getEmail())
                .claim("name", user.getName())
                .claim("scope", user.getRole() == Role.ADMIN ? "user admin" : "user")
                .issueTime(Date.from(now))
                .expirationTime(Date.from(now.plus(ttl)))
                .jwtID(UUID.randomUUID().toString())
                .build();
        var header = new JWSHeader.Builder(JWSAlgorithm.RS256)
                .keyID(key.getKeyID())
                .type(JOSEObjectType.JWT)
                .build();
        try {
            var jwt = new SignedJWT(header, claims);
            jwt.sign(new RSASSASigner(key));
            return new TokenOut(jwt.serialize(), "Bearer", ttl.toSeconds());
        } catch (JOSEException e) {
            throw new IllegalStateException("could not sign the token", e);
        }
    }

    /** The public part only: {"keys":[{"kty":"RSA","kid":"...","n":"...","e":"AQAB",...}]} */
    public Map&lt;String, Object&gt; jwks() {
        return new JWKSet(key.toPublicJWK()).toJSONObject();
    }
}
</code></pre> Claim Significado Verificada pelo gateway <code>iss</code> quem emitiu (<code>boxoffice-auth</code>) sim: precisa bater com <code>JWT_ISSUER</code> <code>aud</code> para quem é (<code>boxoffice</code>) sim: um token de outra API é recusado <code>sub</code> o id do usuário vira <code>X-User-Id</code> <code>scope</code> <code>user</code> ou <code>user admin</code> vira as authorities <code>SCOPE_user</code>, <code>SCOPE_admin</code> <code>exp</code> expiração sim (com 60 s de tolerância de diferença de relógio) <code>kid</code> (header) qual chave assinou usado para escolher a chave certa no JWKS <p>Uma chave nova a cada reinício</p> <p>O <code>TokenService</code> gera o par de chaves RSA em memória quando o <code>auth</code> sobe. Reinicie o <code>auth</code> e todo token emitido antes é rejeitado (<code>kid</code> desconhecido), e duas réplicas do <code>auth</code> assinariam cada uma com uma chave diferente. Em produção, a chave privada fica em um KMS ou gerenciador de segredos, o JWKS lista a chave atual e a anterior durante uma rotação, e as chaves giram em um calendário. Num lab, um reinício que desloga todo mundo é uma vantagem: você vê por que a rotação exige cuidado.</p>

services/auth/src/main/java/boxoffice/auth/AuthService.java<pre><code>package boxoffice.auth;

import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.http.HttpStatus;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class AuthService {

    private static final Logger log = LoggerFactory.getLogger(AuthService.class);

    private final UserRepository users;
    private final TokenService tokens;
    // cost 10 = 2^10 rounds: deliberately slow (tens of ms) to make password guessing expensive
    private final BCryptPasswordEncoder encoder = new BCryptPasswordEncoder(10);
    private final String adminEmail;
    private final String adminPassword;

    public AuthService(UserRepository users, TokenService tokens,
                       @Value("${admin.email}") String adminEmail,
                       @Value("${admin.password}") String adminPassword) {
        this.users = users;
        this.tokens = tokens;
        this.adminEmail = adminEmail;
        this.adminPassword = adminPassword;
    }

    @Transactional
    public UserOut register(RegisterIn in) {
        var email = in.email().toLowerCase();
        if (users.existsByEmail(email)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "e-mail already registered");
        }
        var user = users.save(new User(email, in.name(), encoder.encode(in.password()), Role.USER));
        return UserOut.of(user);
    }

    @Transactional(readOnly = true)
    public TokenOut login(LoginIn in) {
        var user = users.findByEmail(in.email().toLowerCase())
                .filter(u -&gt; encoder.matches(in.password(), u.getPasswordHash()))
                // same answer for "no such user" and "wrong password": do not help attackers
                .orElseThrow(() -&gt; new ResponseStatusException(HttpStatus.UNAUTHORIZED, "invalid credentials"));
        return tokens.issue(user);
    }

    @Transactional(readOnly = true)
    public UserOut find(UUID id) {
        return users.findById(id).map(UserOut::of)
                .orElseThrow(() -&gt; new ResponseStatusException(HttpStatus.NOT_FOUND, "user not found"));
    }

    /** Creates the administrator on the first start (credentials from ADMIN_EMAIL / ADMIN_PASSWORD). */
    @EventListener(ApplicationReadyEvent.class)
    @Transactional
    public void createAdmin() {
        if (!users.existsByEmail(adminEmail)) {
            users.save(new User(adminEmail, "Administrator", encoder.encode(adminPassword), Role.ADMIN));
            log.info("created administrator {}", adminEmail);
        }
    }
}
</code></pre> services/auth/src/main/java/boxoffice/auth/AuthController.java<pre><code>package boxoffice.auth;

