import tools.jackson.core.JacksonException;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.kafka.support.ExponentialBackOffWithMaxRetries;

@Configuration
public class KafkaConfig {

    /** Picked up by Spring Boot's listener container factory (one CommonErrorHandler bean). */
    @Bean
    DefaultErrorHandler errorHandler(KafkaTemplate&lt;String, String&gt; template) {
        // after the retries, publish to &lt;topic&gt;-dlt, same partition, with the exception in headers
        DeadLetterPublishingRecoverer recoverer = new DeadLetterPublishingRecoverer(template);

        ExponentialBackOffWithMaxRetries backOff = new ExponentialBackOffWithMaxRetries(3);
        backOff.setInitialInterval(500L);  // 0.5 s, 1 s, 2 s
        backOff.setMultiplier(2.0);
        backOff.setMaxInterval(5_000L);

        DefaultErrorHandler handler = new DefaultErrorHandler(recoverer, backOff);
        // permanent failures: retrying is pointless, go straight to the DLT
        handler.addNotRetryableExceptions(JacksonException.class, IllegalArgumentException.class);
        return handler;
    }
}
</code></pre> services/notification/src/main/java/boxoffice/notification/DeadLetterListener.java<pre><code>package boxoffice.notification;

import java.nio.charset.StandardCharsets;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.common.header.Header;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.KafkaHeaders;
import org.springframework.stereotype.Component;

@Component
public class DeadLetterListener {

    private static final Logger log = LoggerFactory.getLogger(DeadLetterListener.class);

    private final JdbcClient jdbc;

    public DeadLetterListener(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @KafkaListener(topics = "order-events-dlt", groupId = "notification-dlt")
    public void onDeadLetter(ConsumerRecord&lt;String, String&gt; record) {
        // the listener's exception is wrapped: the CAUSE class says what really failed
        Header cause = record.headers().lastHeader(KafkaHeaders.DLT_EXCEPTION_CAUSE_FQCN);
        String why = cause == null ? "?" : new String(cause.value(), StandardCharsets.UTF_8);
        log.warn("dead letter at {}-{}@{}: {}", record.topic(), record.partition(), record.offset(), why);
        jdbc.sql("""
                INSERT INTO dead_letters (topic, partition, record_offset, record_key, payload, reason)
                VALUES (?, ?, ?, ?, ?, ?)
                """)
                .params(record.topic(), record.partition(), record.offset(), record.key(), record.value(), why)
                .update();
    }
}
</code></pre> services/notification/src/main/java/boxoffice/notification/NotificationController.java<pre><code>package boxoffice.notification;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The synchronous "before" path, used by order in NOTIFY_MODE=sync. */
@RestController
public class NotificationController {

    private final NotificationService notifications;

    public NotificationController(NotificationService notifications) {
        this.notifications = notifications;
    }

    @PostMapping("/notifications")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void send(@RequestBody OrderEvent event) {
        notifications.handle(event);
    }
}
</code></pre> <p>Como flui um registro que falha:</p> <pre><code>sequenceDiagram
    participant K as order-events (partição 3)
    participant L as listener
    participant H as DefaultErrorHandler
    participant D as order-events-dlt (partição 3)
    K-&gt;&gt;L: offset 41
    L--xH: MailSendException (transitória)
    H-&gt;&gt;L: tenta de novo após 0,5 s
    L--xH: falha de novo
    H-&gt;&gt;L: tenta após 1 s, depois 2 s
    L--xH: continua falhando
    H-&gt;&gt;D: publica o registro + headers da exceção
    H-&gt;&gt;K: confirma o offset 42, segue em frente
    K-&gt;&gt;L: offset 42 (a partição volta a andar)</code></pre> <ul> <li>As retentativas acontecem no lugar, bloqueando só aquela partição por no máximo   0,5 + 1 + 2 = 3,5 s; as outras partições continuam andando nas outras threads consumidoras.</li> <li>Exceções não retentáveis pulam o backoff: um JSON malformado ou um endereço recusado vai para a   DLT imediatamente.</li> <li>O Spring Boot liga o único bean <code>CommonErrorHandler</code> à sua fábrica de contêineres de listener; não é   preciso nenhuma configuração extra.</li> </ul> <p>Retentativas bloqueantes vs não bloqueantes</p> <p>O Spring Kafka também oferece <code>@RetryableTopic</code>: registros que falham vão para os tópicos <code>order-events-retry-0</code>, <code>-retry-1</code>… com atrasos, então a partição principal nunca é bloqueada. O preço é ter mais tópicos e nenhuma ordem entre um evento retentado e eventos posteriores da mesma chave. Para e-mails, bloquear alguns segundos é aceitável; para fluxos de alto volume, retentativas não bloqueantes são comuns.</p>

