import boxoffice.order.OrderProperties;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.SendResult;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component
public class OutboxRelay {

    private static final Logger log = LoggerFactory.getLogger(OutboxRelay.class);

    record Pending(UUID id, UUID aggregateId, String eventType, String payload) {
    }

    private final JdbcClient jdbc;
    private final JdbcTemplate jdbcTemplate;
    private final KafkaTemplate&lt;String, String&gt; kafka;
    private final String topic;

    public OutboxRelay(JdbcClient jdbc, JdbcTemplate jdbcTemplate,
                       KafkaTemplate&lt;String, String&gt; kafka, OrderProperties props) {
        this.jdbc = jdbc;
        this.jdbcTemplate = jdbcTemplate;
        this.kafka = kafka;
        this.topic = props.topic();
    }

    @Scheduled(fixedDelayString = "${boxoffice.order.relay-interval-ms:200}")
    @Transactional
    public void relay() throws Exception {
        // SKIP LOCKED: several order replicas can relay in parallel without taking the same rows
        List&lt;Pending&gt; batch = jdbc.sql("""
                SELECT id, aggregate_id, event_type, payload::text AS payload
                FROM outbox
                WHERE published_at IS NULL
                ORDER BY created_at
                LIMIT 100
                FOR UPDATE SKIP LOCKED
                """)
                .query(Pending.class)
                .list();
        if (batch.isEmpty()) {
            return;
        }

        List&lt;CompletableFuture&lt;SendResult&lt;String, String&gt;&gt;&gt; acks = new ArrayList&lt;&gt;();
        for (Pending p : batch) {
            ProducerRecord&lt;String, String&gt; record =
                    new ProducerRecord&lt;&gt;(topic, p.aggregateId().toString(), p.payload());
            record.headers().add("eventId", p.id().toString().getBytes(StandardCharsets.UTF_8));
            record.headers().add("eventType", p.eventType().getBytes(StandardCharsets.UTF_8));
            acks.add(kafka.send(record));
        }
        // wait for every ack; on failure the transaction rolls back and the rows are retried
        CompletableFuture.allOf(acks.toArray(new CompletableFuture&lt;?&gt;[0])).get(10, TimeUnit.SECONDS);

        jdbcTemplate.batchUpdate("UPDATE outbox SET published_at = clock_timestamp() WHERE id = ?",
                batch.stream().map(p -&gt; new Object[] {p.id()}).toList());
        log.info("relayed {} event(s) to {}", batch.size(), topic);
    }

    @Scheduled(cron = "0 0 * * * *")
    @Transactional
    public void purge() {
        int n = jdbcTemplate.update(
                "DELETE FROM outbox WHERE published_at &lt; now() - interval '1 day'");
        log.info("purged {} published outbox row(s)", n);
    }
}
</code></pre> <p>Leia o relay com calma; cada linha responde a uma pergunta sobre falhas:</p> Linha Falha que ela trata <code>FOR UPDATE SKIP LOCKED</code> duas réplicas de <code>order</code> fazendo relay ao mesmo tempo: cada uma trava linhas diferentes, nenhuma espera <code>ORDER BY created_at</code> + chave = <code>orderId</code> eventos do mesmo pedido chegam à mesma partição na ordem do commit <code>allOf(...).get(10, SECONDS)</code> Kafka fora ou lento: a transação é desfeita, as linhas continuam não publicadas, a próxima execução tenta de novo <code>UPDATE ... published_at</code> depois dos acks uma queda antes dele republica o lote (at-least-once) — nunca o perde <code>purge()</code> a tabela não cresce para sempre; linhas publicadas ficam um dia para depuração

